INSERT INTO public.rule_document_versions (document_id,version_label,status,changelog)
SELECT id,'1.0 Draft','proposed','First DGD Rules of Play draft, open for review. Not yet in effect.' FROM public.rule_documents WHERE code='rules_of_play';
INSERT INTO public.rule_entries (version_id,number,parent_number,kind,title,body,is_protected,sort)
SELECT (SELECT v.id FROM public.rule_document_versions v JOIN public.rule_documents d ON d.id=v.document_id WHERE d.code='rules_of_play' AND v.version_label='1.0 Draft'), x.* FROM (VALUES ('100',NULL,'section','The Game','',false,100),('100.1','100','rule','Object of play','Each player completes every hole of the layout in as few throws and penalty throws as possible. The lowest total wins.',false,101),('100.2','100','rule','Spirit of the game','Players are expected to call their own rules honestly, respect the course and keep play moving.',false,102),('110',NULL,'section','Definitions','',false,200),('110.1','110','rule','Lie','The spot on the playing surface where a player''s previous throw came to rest, or a spot given by rule.',false,201),('110.2','110','rule','Marker','Any approved small disc or object used to mark a lie.',false,202),('110.3','110','rule','Out-of-bounds (OB)','Any area the event or course has designated as out of play. A disc is OB when it rests clearly inside that area.',false,203),('110.4','110','rule','Hole complete','A hole is complete when the disc comes to rest supported by the basket''s chains or tray, or as stated for an alternate target.',false,204),('120',NULL,'section','Application of the Rules','',false,300),('120.1','120','rule','Who the rules cover','These rules govern every DGD-sanctioned round and serve as the default for custom events that choose DGD rules.',false,301),('120.2','120','rule','Event-specific rules','Events may add course-specific rules through an approved overlay. Overlays may clarify a course but may not replace a protected rule.',false,302),('120.3','120','rule','When something is not covered','If no rule applies, the group decides using common sense and fairness; in a sanctioned event the Tournament Director has the final word.',false,303),('130',NULL,'section','Order of Play','',false,400),('130.1','130','rule','On the tee','The first hole follows the card order. Afterward, the lowest score on the previous hole throws first; ties keep the previous order.',false,401),('130.2','130','rule','In the fairway','The player farthest from the target throws next, unless the group agrees otherwise for safety or pace.',false,402),('140',NULL,'section','The Throw','',false,500),('140.1','140','rule','A valid throw','A throw is any intentional release of the disc toward play. A disc dropped or slipped before a throwing motion is not a throw.',false,501),('140.2','140','rule','Practice throws','Practice throws during a round are not allowed and cost one penalty throw.',false,502),('150',NULL,'section','The Lie & Stance','',false,600),('150.1','150','rule','Supporting point','At release the player must keep at least one supporting point touching the playing surface behind the marker and within a small area around the line of play.',true,601),('150.2','150','rule','Putting zone','Within the defined putting zone the player must show balance behind the marker after release before moving toward the target.',true,602),('160',NULL,'section','Tees & Starting Play','',false,700),('160.1','160','rule','Teeing area','The first throw on each hole is taken from inside the designated tee. If no tee exists, the group marks one for the hole.',false,701),('160.2','160','rule','Wrong tee','Throwing from the wrong tee is a misplay; correct it before the next throw.',false,702),('170',NULL,'section','Obstacles & Relief','',false,800),('170.1','170','rule','Playing the course as found','Players may not alter the course to gain an advantage, such as bending branches or removing fixed objects.',false,801),('170.2','170','rule','Free relief','Relief without penalty is available from casual obstacles such as standing water, loose debris or another player''s equipment.',false,802),('180',NULL,'section','Regulated Routes','',false,900),('180.1','180','rule','Mandatory routes (mandos)','A mando requires the disc to pass a set side of an object. Missing it costs one penalty throw.',false,901),('180.2','180','rule','Where to play after a missed mando','Play from the event''s designated drop zone if one exists, otherwise from the previous lie.',false,902),('180.3','180','rule','Event clarification','Each mando is described in the event rule overlay, with the exact object and direction.',false,903),('190',NULL,'section','Regulated Positions','',false,1000),('190.1','190','rule','Drop zones','A drop zone is an alternate lie set by the event. Its use and penalty are listed in the event overlay.',false,1001),('190.2','190','rule','Elevated or above-ground lies','If an event declares an above-ground rule, a disc resting above the set height takes one penalty throw and is played from below.',false,1002),('200',NULL,'section','Regulated Areas','',false,1100),('200.1','200','rule','Out-of-bounds','A disc OB takes one penalty throw and is played from where it last crossed into OB, a drop zone, or the previous lie as the event allows.',true,1101),('200.2','200','rule','Hazard areas','A hazard area costs one penalty throw but play continues from where the disc came to rest.',true,1102),('200.3','200','rule','Lost disc','A disc not found within three minutes of search is lost; play from the previous lie with one penalty throw.',true,1103),('210',NULL,'section','Completing the Hole','',false,1200),('210.1','210','rule','Holing out','The hole is complete when the disc rests in the target as defined in 110.',false,1201),('210.2','210','rule','Missing a hole','A player who skips a hole receives the hole''s par plus four.',false,1202),('220',NULL,'section','Scoring','',false,1300),('220.1','220','rule','Recording scores','Each player''s score is recorded hole by hole on the official scorecard, including penalties.',true,1301),('220.2','220','rule','Signing the card','At the end of a round every player confirms the card. Errors found after confirmation are corrected only through the Tournament Director.',true,1302),('230',NULL,'section','Special Throws','',false,1400),('230.1','230','rule','Provisional throw','When a ruling is uncertain, a player may throw a provisional with the group''s agreement. The ruling decides which throw counts.',false,1401),('230.2','230','rule','Retracing','A player may retrieve a disc and replay from the previous lie with one penalty throw.',false,1402),('240',NULL,'section','Interference','',false,1500),('240.1','240','rule','Disc moved by another','If a disc is moved by a person or animal, it is returned to its original spot without penalty.',false,1501),('240.2','240','rule','Hitting a person','A disc that strikes a person is played where it comes to rest.',false,1502),('250',NULL,'section','Misplay','',false,1600),('250.1','250','rule','Playing the wrong disc','Throwing another player''s disc is a misplay; correct it with one penalty throw.',false,1601),('250.2','250','rule','Wrong lie','Throwing from a wrong lie costs one penalty throw and must be corrected before teeing off on the next hole.',false,1602),('260',NULL,'section','Courtesy & Pace of Play','',false,1700),('260.1','260','rule','Courtesy','Do not distract a player who is throwing. Keep phones quiet and stay out of the line of play.',false,1701),('260.2','260','rule','Time to throw','A player has thirty seconds to throw after arriving at the lie and having a clear path. Excess delay may earn a warning, then a penalty throw.',false,1702),('270',NULL,'section','Equipment','',false,1800),('270.1','270','rule','Approved discs','Only discs that meet the DGD Equipment Standard may be used in sanctioned play.',false,1801),('270.2','270','rule','Damaged discs','A disc cracked or reshaped so that it flies unlike its original form may not be used.',false,1802),('280',NULL,'section','Officiating & Rulings','',false,1900),('280.1','280','rule','Calling a rule','Any player in the group may call a rule. The group must agree, or ask for an official.',true,1901),('280.2','280','rule','Official rulings','An official''s ruling stands for the round. Players may appeal through the DGD Conduct & Discipline Code.',true,1902),('280.3','280','rule','Recording rulings','Every official ruling in a sanctioned event is recorded with the hole, rule number and decision.',true,1903)) AS x(number,parent_number,kind,title,body,is_protected,sort);